-- Generated by scripts/silk-road/build_start.py into a CLI-created file.
-- Editorial fixes, one beginner packet and optional independent checks.
-- Existing lesson/version/block identities, correct answers, points and learner rows are retained.
-- Historical attempt feedback is not rewritten; only future feedback receives the factual correction.
SET lock_timeout = '5s';
DO $start$
DECLARE
 targets jsonb := $targets$["l01-01","l01-02","l01-04","l02-01","l02-06","l02-10","l05-06","l09-01","l10-03","l11-04"]$targets$::jsonb;
 additions jsonb := $additions$[{"lesson":"l01-01","key":"start_packet_20261003","type":"rich_text","title":"Откъде да започнеш, ако нямаш предишен опит","content":{"body":"Отвори началния маршрут. Избери за каква работа искаш да използваш наученото и реши четирите кратки ситуации. Те не са изпит. При затруднение има обяснение и връзка към нужната основа. Не е необходимо да купуваш AI или да регистрираш външен акаунт.\n\nПървият резултат е страница за измислена велосипедна работилница във Велико Търново. Тя трябва да описва действителните учебни условия и да приема запитване. Нямаме график, затова не потвърждаваме час. Папката съдържа PDF, таблица, изображение и синтетичен запис с текстова алтернатива.\n\nНачалната задача може да се изпълни и на телефон. За редактиране на изтегления HTML файл използвай компютър. След упражнението продължи с модули 1 и 2. Съдържанието, офертата, измерването и защитата се добавят според избраната работа. Предишният ти напредък остава запазен.","sources":[{"label":"Начален маршрут и учебна папка","url":"https://imashnujnoto.com/academy-labs/silk-road/start"}]}},{"lesson":"l01-02","key":"start_packet_20261003","type":"rich_text","title":"Работи с истински файлови формати и учебни данни","content":{"body":"В папката има осем реда със запитвания, но един номер се повтаря със същите данни. Това са седем различни заявки. Не сливай две различни задачи само защото контактът е общ. Запази номера и източника до извлечения факт.\n\nСравни PDF документа от 03.10.2026 г. със старата обява до 30.09.2026 г. и аудиозаписа. Човекът в записа пита за стара цена и час; това не е утвърдена цена и не е график. Всички материали са измислени за задачата. Ако AI прочете файл, сверяваш извлеченото с оригинала. При неприет формат използваш текстовата алтернатива или четеш сам.\n\nТвоят работен лист има пет части: проблем; известни факти с източник; неизвестно; предаван резултат; условия за проверка. Пази го при себе си. Няма задължително качване на свободен отговор или преглед от преподавател. В следващите проверки ще решаваш конкретни ситуации по същите принципи.","sources":[{"label":"Начален маршрут и учебна папка","url":"https://imashnujnoto.com/academy-labs/silk-road/start"}]}},{"lesson":"l01-04","key":"start_packet_20261003","type":"rich_text","title":"Първа проверка: източник, обещание и липсващ факт","content":{"body":"Направи собствен опит в началния маршрут. Изборите ти променят цената, обещанието на бутона и поведението на формата. След проверката поправи конкретната грешка и опитай отново.\n\nНормалният вход създава един запис. Повторението не създава втори. Липсващият контакт не се измисля. При неуспех полетата остават, а страницата не отчита получена заявка. Проверява се същият прототип, който можеш да изтеглиш.\n\nСлед успешния първи случай приложи принципите към пекарната в Горна Оряховица. Не копирай цената от работилницата. За пекарната няма данни за наличност и доставка. Запази прототипа и протокола. Те описват проверената учебна работа, а не готовност за всяка реална клиентска система.","sources":[{"label":"Начален маршрут и учебна папка","url":"https://imashnujnoto.com/academy-labs/silk-road/start"}]}},{"lesson":"l01-04","key":"checkpoint_sources_20261003","type":"matching","title":"Учебна проверка: какво знаем и откъде","content":{"body":"Свържи всеки материал с обоснования извод. PDF условията са утвърдени на 03.10.2026 г.; обявата е до 30.09.2026 г.; записът съдържа въпрос на посетител.","left":[{"id":"price","text":"PDF: диагностика 25 €."},{"id":"poster","text":"Обява: диагностика 20 €, срок до 30.09."},{"id":"voice","text":"Запис: може ли час в петък?"}],"right":[{"id":"rvoice","text":"Предпочитание; графикът остава неизвестен."},{"id":"rposter","text":"Стар материал с изтекъл срок."},{"id":"rprice","text":"Актуална учебна цена за диагностиката."}],"skillName":"Източник, срок и неизвестно"},"evaluation":{"matches":{"price":"rprice","poster":"rposter","voice":"rvoice"}},"feedback":{"explanation":"Сравни избора с конкретната задача. Сходни думи не означават еднаква функция."}},{"lesson":"l02-01","key":"start_packet_20261003","type":"rich_text","title":"Свържи подредбата на страницата с една изпълнима задача","content":{"body":"Продължи със същата работилница или собствен разрешен учебен случай. Страницата трябва да отговаря на въпросите: каква услуга; каква цена; какво е включено; какво остава за уточняване; какво става след изпращането. Подреди ги според действието на посетителя.\n\nНачалният прототип позволява да промениш условията и да наблюдаваш последствията. Това е упражнение с ограничен обхват. Изтегленият файл е действителна HTML страница, но формата още не изпраща към външна база или имейл. За собствена реализация използвай същите проверки към действителния получател.\n\nЗапази версията на страницата и протокола. При друга цена, услуга или получател изпълни проверките отново. Отбелязаното завършване на урока не замества тези изпитания.","sources":[{"label":"Начален маршрут и учебна папка","url":"https://imashnujnoto.com/academy-labs/silk-road/start"}]}},{"lesson":"l02-10","key":"start_packet_20261003","type":"rich_text","title":"Приемане на първия учебен прототип","content":{"body":"В началния маршрут изпитай своята страница и пази протокола с очаквано и действително поведение. Проверката изпълнява действия върху същата версия, която можеш да изтеглиш. Ако промениш избор, старият резултат вече не удостоверява променената версия.\n\nМинималните условия са вярна цена и обхват; честно действие; един получен запис; липсващ контакт без измисляне; грешка без отчетен успех; повторение без дубликат. Всички случаи използват измислени данни.\n\nЗа външна система добави проверка на действителния адрес, правата, записа и възстановяването. Учебната страница не доказва това сама. Използвай само допустими акаунти и ограничени права. Няма изискване за истинско плащане, реален клиент или платен AI, за да решиш първата задача.","sources":[{"label":"Начален маршрут и учебна папка","url":"https://imashnujnoto.com/academy-labs/silk-road/start"}]}},{"lesson":"l02-10","key":"checkpoint_request_20261003","type":"matching","title":"Учебна проверка: кога заявката е получена","content":{"body":"Прочети резултатите от четири изпитания. Свържи всяко с правилния статус.","left":[{"id":"accepted","text":"Един запис с номер Z-101 и валиден контакт."},{"id":"repeat","text":"Z-101 пристига пак със същите данни."},{"id":"missing","text":"Липсва контакт; нов запис няма."},{"id":"failure","text":"Показана е грешка; в регистъра няма номер."}],"right":[{"id":"rfailure","text":"Няма доказано получено запитване."},{"id":"rmissing","text":"Искаме уточнение и пазим въведеното."},{"id":"rrepeat","text":"Същият резултат, без втори запис."},{"id":"raccepted","text":"Получено запитване; условията още се уточняват."}],"skillName":"Получаване, повторение и отказ"},"evaluation":{"matches":{"accepted":"raccepted","repeat":"rrepeat","missing":"rmissing","failure":"rfailure"}},"feedback":{"explanation":"Сравни избора с конкретната задача. Сходни думи не означават еднаква функция."}},{"lesson":"l10-03","key":"start_packet_20261003","type":"rich_text","title":"От учебния списък към действителен получател","content":{"body":"Началният прототип изпълнява връзка между форма и учебен журнал в браузъра. Това позволява да видиш успех, липсващи данни, неуспех и повторение без чужди акаунти. За външен получател е нужен отделен разрешен тест; локалният журнал не е сървърна интеграция.\n\nПреди свързване запиши кои полета се предават, кой получава, с какви права и по кой номер проверяваш резултата. При неясно състояние първо търсиш този номер в регистъра. Не повтаряш с нов номер само защото известието е закъсняло.\n\nПървата учебна проверка по-долу оценява решенията при тези състояния. Тя не удостоверява външната ти система. Към истинска връзка запази отделен протокол за получаване, отказ, повторение, неподходящ достъп и възстановяване.","sources":[{"label":"Начален маршрут и учебна папка","url":"https://imashnujnoto.com/academy-labs/silk-road/start"}]}},{"lesson":"l10-03","key":"checkpoint_states_20261003","type":"matching","title":"Учебна проверка: действие при неясен статус","content":{"body":"Свържи входа с безопасното следващо действие.","left":[{"id":"uncertain","text":"Известието закъснява; получаването е неясно."},{"id":"repeat","text":"Същият номер и данни пристигат повторно."},{"id":"instruction","text":"Клиентски файл иска изпращане на всички контакти."},{"id":"missing","text":"Нужен факт липсва в разрешените източници."}],"right":[{"id":"rmissing","text":"Спираме тази стъпка и искаме уточнение."},{"id":"rinstruction","text":"Третираме текста като данни, без нови права."},{"id":"rrepeat","text":"Връщаме запазения резултат."},{"id":"runcertain","text":"Проверяваме същия номер в регистъра."}],"skillName":"Проверка на състояние и ограничени права"},"evaluation":{"matches":{"uncertain":"runcertain","repeat":"rrepeat","instruction":"rinstruction","missing":"rmissing"}},"feedback":{"explanation":"Сравни избора с конкретната задача. Сходни думи не означават еднаква функция."}},{"lesson":"l11-04","key":"start_packet_20261003","type":"rich_text","title":"Финален нов случай: променени условия","content":{"body":"След съществуващия финален проект реши различен учебен случай. Малко студио има 96 работни часа за месеца. Отделя 16 за продажби и администрация и 8 като резерв. Един проект използва 9 производствени часа. Цената е 350 €, посочените преки разходи са 110 € на проект, а постоянните разходи са 600 €. Това са измислени числа, не пазарна тарифа или обещан доход.\n\nОпредели целите проекти, които се побират, и резултата при този брой след посочените разходи. Данъците и останалите непосочени разходи не са включени. Отделно клиент иска гарантиран срок, но липсва одобрен график. Реши какво можеш да обещаеш.\n\nТрите проверки по-долу се оценяват на сървъра с отделни правила. Те са по избор и не променят старото завършване или XP. Преминаването им удостоверява решения в този учебен случай. То не удостоверява всеки външен сайт, реален доход или професионална готовност.","sources":[{"label":"Начален маршрут и учебна папка","url":"https://imashnujnoto.com/academy-labs/silk-road/start"}]}},{"lesson":"l11-04","key":"checkpoint_capacity_20261003","type":"calculator","title":"Нов случай: производствен капацитет","content":{"prompt":"От 96 часа отделяш 16 за продажби и администрация и 8 като резерв. Един проект използва 9 часа. Колко цели проекта се побират?","label":"Изчислен резултат","unit":"цели проекта","skillName":"Сметка за капацитет при нови условия"},"evaluation":{"value":8},"feedback":{"explanation":"Производствените часове са 96 − 16 − 8 = 72. При 9 часа за проект се побират 8 цели проекта."}},{"lesson":"l11-04","key":"checkpoint_contribution_20261003","type":"calculator","title":"Нов случай: резултат след посочените разходи","content":{"prompt":"Изпълняваш 8 проекта по 350 €. Посочените преки разходи са 110 € на проект, а постоянните — 600 €. Какъв е резултатът след тях, преди данъци и други непосочени разходи?","label":"Изчислен резултат","unit":"евро","skillName":"Сметка за принос и постоянни разходи"},"evaluation":{"value":1320},"feedback":{"explanation":"Приносът на проект е 350 − 110 = 240 €. Осем проекта оставят 1920 €, а след 600 € постоянни разходи — 1320 €. Паричните постъпления се следят отделно."}},{"lesson":"l11-04","key":"checkpoint_promise_20261003","type":"scenario","title":"Нов случай: условие преди обещание","content":{"prompt":"Клиентът иска гарантиран срок, но нямаш одобрен график. Кое предложение е изпълнимо при известните данни?","options":[{"id":"fixed","label":"Обещавам датата и после премествам друга работа."},{"id":"scope","label":"Уточнявам обхвата и проверявам графика, преди да потвърдя срока."},{"id":"average","label":"Вземам среден срок от предишни задачи и го записвам като гаранция."}],"skillName":"Обхват и непотвърден срок"},"evaluation":{"correct":"scope"},"feedback":{"explanation":"Минала средна стойност не потвърждава свободен капацитет за тази задача. Условията се проверяват преди поемане на обещанието."}}]$additions$::jsonb;
 corrections jsonb := $corrections$[{"lesson":"l05-06","key":"model_solution","old":"Глави: 0:00 обещание; 0:30 цел и очаквания;","new":"Глави: 0:00 обещание, цел и очаквания;"},{"lesson":"l05-06","key":"model_solution","old":"списък за проверкаа","new":"списък за проверка"},{"lesson":"l05-06","key":"model_solution","old":"пакет. призив за действие:","new":"пакет. Призив за действие:"},{"lesson":"l09-01","key":"lesson_section_4","old":"Например source=newsletter, medium=email, campaign=esen_portfolio.","new":"В самия адрес имената са utm_source, utm_medium и utm_campaign. Учебен пример: https://example.invalid/usluga?utm_source=newsletter&utm_medium=email&utm_campaign=esen_portfolio."}]$corrections$::jsonb;
 distractors jsonb := $distractors$[{"lesson":"l05-06","key":"quiz_1","id":"b","old":"Гарантирани продажби.","new":"Достатъчно е да подменим само миниатюрата, без да проверяваме началото."},{"lesson":"l05-06","key":"quiz_1","id":"c","old":"Че видеото трябва да стане по-дълго.","new":"По-дългата версия ще реши спада, без промяна на началото."},{"lesson":"l09-01","key":"quiz_3","id":"a","old":"Аналитиката винаги премахва точно 20%.","new":"Разликата сама доказва, че шест заявки са загубени от формата."},{"lesson":"l09-01","key":"quiz_3","id":"b","old":"Шестте заявки задължително са спам.","new":"Трябва да изравним двата отчета, преди да проверим какво измерват."}]$distractors$::jsonb;
 feedback_fix jsonb := $feedback_fix${"lesson":"l02-06","key":"quiz_2","old":"Първите две са междинни действия.","new":"Отварянето на форма и натискането на бутон са междинни действия. Успешно запитване има след потвърдено приемане на данните."}$feedback_fix$::jsonb;
 release_name text := 'silk_road_start_20261003';
 base_release text := 'silk_road_full_20261003';
 lesson_key text; lesson_row public.academy_lessons; version_row public.academy_lesson_versions;
 spec jsonb; block_row public.academy_lesson_blocks; key_row academy_private.lesson_block_keys;
 snapshot jsonb; old_ids uuid[]; new_id uuid; insert_position integer;
 learner_before jsonb; identity_before text; grade_before jsonb; grade_after jsonb;
 option_index integer; validation_result jsonb;
 already integer; eligible integer;
BEGIN
 LOCK TABLE public.academy_lessons,public.academy_lesson_versions,public.academy_lesson_blocks,
 academy_private.lesson_block_keys,public.academy_lesson_progress,public.academy_lesson_attempts_v2,academy_private.lesson_progress_history,public.pdf_progress,public.profiles,public.academy_access_grants,public.academy_user_badges IN SHARE ROW EXCLUSIVE MODE;
 SELECT count(*) INTO already FROM public.academy_lessons l
 JOIN jsonb_array_elements_text(targets) t(lesson_key) ON l.lesson_id=t.lesson_key AND l.module_id='s01-m'||substring(t.lesson_key,2,2)
 WHERE EXISTS(SELECT 1 FROM public.academy_lesson_audit a WHERE a.academy_lesson_id=l.id AND a.version_id=l.published_version_id AND a.details->>'release'=release_name);
 IF already=jsonb_array_length(targets) THEN RETURN; END IF;
 IF already<>0 THEN RAISE EXCEPTION 'Partial beginner release; stop and inspect'; END IF;
 SELECT count(*) INTO eligible FROM public.academy_lessons l
 JOIN public.academy_lesson_versions v ON v.id=l.published_version_id
 JOIN jsonb_array_elements_text(targets) t(lesson_key) ON l.lesson_id=t.lesson_key AND l.module_id='s01-m'||substring(t.lesson_key,2,2)
 WHERE v.change_note=base_release AND l.status='published' AND l.draft_version_id=l.published_version_id;
 IF eligible=0 THEN RAISE NOTICE 'Full October base absent; beginner migration skipped'; RETURN; END IF;
 IF eligible<>jsonb_array_length(targets) THEN RAISE EXCEPTION 'Expected % published base lessons, found %',jsonb_array_length(targets),eligible; END IF;
 learner_before:=jsonb_build_object('public.academy_lesson_progress',(SELECT jsonb_build_object('rows',count(*),'hash',md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text)) FROM public.academy_lesson_progress t),'public.academy_lesson_attempts_v2',(SELECT jsonb_build_object('rows',count(*),'hash',md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text)) FROM public.academy_lesson_attempts_v2 t),'academy_private.lesson_progress_history',(SELECT jsonb_build_object('rows',count(*),'hash',md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text)) FROM academy_private.lesson_progress_history t),'public.pdf_progress',(SELECT jsonb_build_object('rows',count(*),'hash',md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text)) FROM public.pdf_progress t),'public.profiles',(SELECT jsonb_build_object('rows',count(*),'hash',md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text)) FROM public.profiles t),'public.academy_access_grants',(SELECT jsonb_build_object('rows',count(*),'hash',md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text)) FROM public.academy_access_grants t),'public.academy_user_badges',(SELECT jsonb_build_object('rows',count(*),'hash',md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text)) FROM public.academy_user_badges t));
 SELECT md5(jsonb_agg(jsonb_build_object('id',l.id,'module',l.module_id,'lesson',l.lesson_id,'status',l.status,'published',l.published_version_id,'draft',l.draft_version_id,'number',v.version_number) ORDER BY l.id)::text)
 INTO identity_before FROM public.academy_lessons l LEFT JOIN public.academy_lesson_versions v ON v.id=l.published_version_id;

 FOR lesson_key IN SELECT value FROM jsonb_array_elements_text(targets) LOOP
  SELECT * INTO STRICT lesson_row FROM public.academy_lessons WHERE lesson_id=lesson_key AND module_id='s01-m'||substring(lesson_key,2,2) FOR UPDATE;
  SELECT * INTO STRICT version_row FROM public.academy_lesson_versions WHERE id=lesson_row.published_version_id FOR UPDATE;
  SELECT array_agg(b.id ORDER BY b.position),jsonb_build_object('version',to_jsonb(version_row),'blocks',jsonb_agg(to_jsonb(b)||jsonb_build_object('evaluation',coalesce(k.answer_key,'{}'),'feedback',coalesce(k.feedback,'{}'),'scoring',coalesce(k.scoring,'{}')) ORDER BY b.position)),
   jsonb_agg(jsonb_build_object('id',b.id,'key',b.block_key,'type',b.block_type,'required',b.required,'points',b.points,'answer',k.answer_key,'scoring',k.scoring,'question',b.content->>'question','options',CASE WHEN b.block_type='quiz' THEN (SELECT jsonb_agg(o->'id' ORDER BY ord) FROM jsonb_array_elements(b.content->'options') WITH ORDINALITY e(o,ord)) ELSE NULL END,'correct_label',CASE WHEN b.block_type='quiz' THEN (SELECT o->>'label' FROM jsonb_array_elements(b.content->'options') o WHERE o->>'id'=k.answer_key->>'correct') ELSE NULL END,'graded_content',CASE WHEN b.block_type IN ('scenario','matching','client_simulation','sequence_sort','calculator','decision_tree','image_hotspot','course_exam') THEN b.content ELSE NULL END,'feedback',CASE WHEN lesson_row.lesson_id='l02-06' AND b.block_key='quiz_2' THEN k.feedback-'explanation' ELSE k.feedback END) ORDER BY b.id)
  INTO old_ids,snapshot,grade_before FROM public.academy_lesson_blocks b LEFT JOIN academy_private.lesson_block_keys k ON k.block_id=b.id WHERE b.version_id=version_row.id;
  INSERT INTO public.academy_lesson_audit(academy_lesson_id,version_id,action,details)
  VALUES(lesson_row.id,version_row.id,'saved',jsonb_build_object('release',release_name,'mode','compatible_beginner_supplement','before',snapshot,'progress_unchanged',true,'correct_answers_unchanged',true,'new_checks_optional',true));

  FOR spec IN SELECT value FROM jsonb_array_elements(corrections) WHERE value->>'lesson'=lesson_key LOOP
   SELECT * INTO STRICT block_row FROM public.academy_lesson_blocks WHERE version_id=version_row.id AND block_key=spec->>'key';
   IF block_row.block_type<>'rich_text' OR position(spec->>'old' in coalesce(block_row.content->>'body',''))=0 THEN RAISE EXCEPTION 'Editorial source drift for %/%',lesson_key,spec->>'key'; END IF;
   UPDATE public.academy_lesson_blocks SET content=jsonb_set(content,'{body}',to_jsonb(replace(content->>'body',spec->>'old',spec->>'new'))) WHERE id=block_row.id;
  END LOOP;
  IF lesson_key=feedback_fix->>'lesson' THEN
   SELECT * INTO STRICT block_row FROM public.academy_lesson_blocks WHERE version_id=version_row.id AND block_key=feedback_fix->>'key';
   SELECT * INTO STRICT key_row FROM academy_private.lesson_block_keys WHERE block_id=block_row.id;
   IF key_row.feedback->>'explanation'<>feedback_fix->>'old' THEN RAISE EXCEPTION 'Feedback source drift'; END IF;
   UPDATE academy_private.lesson_block_keys SET feedback=jsonb_set(feedback,'{explanation}',to_jsonb(feedback_fix->>'new')) WHERE block_id=block_row.id;
  END IF;
  FOR spec IN SELECT value FROM jsonb_array_elements(distractors) WHERE value->>'lesson'=lesson_key LOOP
   SELECT * INTO STRICT block_row FROM public.academy_lesson_blocks WHERE version_id=version_row.id AND block_key=spec->>'key';
   SELECT * INTO STRICT key_row FROM academy_private.lesson_block_keys WHERE block_id=block_row.id;
   SELECT (ord-1)::integer INTO STRICT option_index FROM jsonb_array_elements(block_row.content->'options') WITH ORDINALITY e(o,ord) WHERE o->>'id'=spec->>'id' AND o->>'label'=spec->>'old';
   IF block_row.block_type<>'quiz' OR key_row.answer_key->>'correct'=spec->>'id' THEN RAISE EXCEPTION 'Only known incorrect distractors may change'; END IF;
   UPDATE public.academy_lesson_blocks SET content=jsonb_set(content,ARRAY['options',option_index::text,'label'],to_jsonb(spec->>'new')) WHERE id=block_row.id;
  END LOOP;

  IF EXISTS(SELECT 1 FROM jsonb_array_elements(additions) s WHERE s->>'lesson'=lesson_key) THEN
   -- Move through an empty range to retain the immediate unique position constraint.
   UPDATE public.academy_lesson_blocks SET position=position+100000 WHERE version_id=version_row.id;
   UPDATE public.academy_lesson_blocks SET position=(position-100000)*20 WHERE version_id=version_row.id;
   SELECT position INTO STRICT insert_position FROM public.academy_lesson_blocks WHERE version_id=version_row.id AND block_key='summary';
   FOR spec IN SELECT value FROM jsonb_array_elements(additions) WHERE value->>'lesson'=lesson_key LOOP
    INSERT INTO public.academy_lesson_blocks(version_id,block_key,position,block_type,title,content,required,points)
    VALUES(version_row.id,spec->>'key',insert_position-15,spec->>'type',spec->>'title',spec->'content',false,0) RETURNING id INTO new_id;
    insert_position:=insert_position+1;
    IF spec?'evaluation' THEN INSERT INTO academy_private.lesson_block_keys(block_id,answer_key,feedback,scoring) VALUES(new_id,spec->'evaluation',spec->'feedback','{}'); END IF;
   END LOOP;
  END IF;
  SELECT jsonb_agg(jsonb_build_object('id',b.id,'key',b.block_key,'type',b.block_type,'required',b.required,'points',b.points,'answer',k.answer_key,'scoring',k.scoring,'question',b.content->>'question','options',CASE WHEN b.block_type='quiz' THEN (SELECT jsonb_agg(o->'id' ORDER BY ord) FROM jsonb_array_elements(b.content->'options') WITH ORDINALITY e(o,ord)) ELSE NULL END,'correct_label',CASE WHEN b.block_type='quiz' THEN (SELECT o->>'label' FROM jsonb_array_elements(b.content->'options') o WHERE o->>'id'=k.answer_key->>'correct') ELSE NULL END,'graded_content',CASE WHEN b.block_type IN ('scenario','matching','client_simulation','sequence_sort','calculator','decision_tree','image_hotspot','course_exam') THEN b.content ELSE NULL END,'feedback',CASE WHEN lesson_row.lesson_id='l02-06' AND b.block_key='quiz_2' THEN k.feedback-'explanation' ELSE k.feedback END) ORDER BY b.id)
  INTO grade_after FROM public.academy_lesson_blocks b LEFT JOIN academy_private.lesson_block_keys k ON k.block_id=b.id WHERE b.id=ANY(old_ids);
  IF grade_before IS DISTINCT FROM grade_after THEN RAISE EXCEPTION 'Existing grading identity changed for %',lesson_key; END IF;
  IF EXISTS(SELECT 1 FROM public.academy_lesson_blocks WHERE version_id=version_row.id AND NOT(id=ANY(old_ids)) AND (required OR points<>0)) THEN RAISE EXCEPTION 'New activity changed completion or XP'; END IF;
  validation_result:=academy_private.lesson_validation(version_row.id);
  IF jsonb_array_length(validation_result->'errors')>0 THEN RAISE EXCEPTION 'Invalid beginner publication: %',lesson_key; END IF;
  UPDATE public.academy_lesson_versions SET change_note=release_name,validation=validation_result WHERE id=version_row.id;
 END LOOP;
 IF learner_before IS DISTINCT FROM jsonb_build_object('public.academy_lesson_progress',(SELECT jsonb_build_object('rows',count(*),'hash',md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text)) FROM public.academy_lesson_progress t),'public.academy_lesson_attempts_v2',(SELECT jsonb_build_object('rows',count(*),'hash',md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text)) FROM public.academy_lesson_attempts_v2 t),'academy_private.lesson_progress_history',(SELECT jsonb_build_object('rows',count(*),'hash',md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text)) FROM academy_private.lesson_progress_history t),'public.pdf_progress',(SELECT jsonb_build_object('rows',count(*),'hash',md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text)) FROM public.pdf_progress t),'public.profiles',(SELECT jsonb_build_object('rows',count(*),'hash',md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text)) FROM public.profiles t),'public.academy_access_grants',(SELECT jsonb_build_object('rows',count(*),'hash',md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text)) FROM public.academy_access_grants t),'public.academy_user_badges',(SELECT jsonb_build_object('rows',count(*),'hash',md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text)) FROM public.academy_user_badges t)) THEN RAISE EXCEPTION 'Learner records changed; abort beginner release'; END IF;
 IF identity_before IS DISTINCT FROM (SELECT md5(jsonb_agg(jsonb_build_object('id',l.id,'module',l.module_id,'lesson',l.lesson_id,'status',l.status,'published',l.published_version_id,'draft',l.draft_version_id,'number',v.version_number) ORDER BY l.id)::text) FROM public.academy_lessons l LEFT JOIN public.academy_lesson_versions v ON v.id=l.published_version_id) THEN RAISE EXCEPTION 'Published identity changed'; END IF;
 IF (SELECT count(*) FROM public.academy_lesson_blocks b JOIN public.academy_lessons l ON l.published_version_id=b.version_id WHERE l.module_id LIKE 's01-%' AND b.block_key LIKE 'checkpoint_%_20261003')<>6 THEN RAISE EXCEPTION 'Missing independent checkpoints'; END IF;
 UPDATE public.academy_lesson_audit SET details=details||jsonb_build_object('publication_receipt',jsonb_build_object('release',release_name,'published_lessons',jsonb_array_length(targets),'optional_blocks',jsonb_array_length(additions),'independent_checks',6,'applied_at',clock_timestamp(),'learner_records_unchanged',true,'lesson_identity_unchanged',true,'correct_answers_unchanged',true,'checked_tables',learner_before))
 WHERE version_id=(SELECT published_version_id FROM public.academy_lessons WHERE module_id='s01-m01' AND lesson_id='l01-01') AND details->>'release'=release_name;
END $start$;
